PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3x3_bf16(
    .param .u64 p_in,
    .param .u64 p_w,
    .param .u64 p_out,
    .param .s32 p_H,
    .param .s32 p_W,
    .param .s32 p_OH,
    .param .s32 p_OW
)
{
    .reg .pred p;
    .reg .b16 h_in, h_w, h_out;
    .reg .b32 r_tx, r_ty, r_bx, r_by, r_bz, r_ntx, r_nty;
    .reg .b32 r_x, r_y, r_n, r_oc, r_H, r_W, r_OH, r_OW;
    .reg .b32 r_ci, r_ky, r_kx, r_ci9, r_wrow, r_tmp32;
    .reg .b64 r_in, r_w, r_out, r_HW, r_CHW, r_W64;
    .reg .b64 r_n64, r_x64, r_yW, r_base, r_inrow, r_wbase;
    .reg .b64 r_ciHW, r_kyW, r_delta, r_off, r_addr, r_waddr;
    .reg .f32 f_acc, f_in, f_w;

    ld.param.u64 r_in, [p_in];
    ld.param.u64 r_w, [p_w];
    ld.param.u64 r_out, [p_out];
    ld.param.s32 r_H, [p_H];
    ld.param.s32 r_W, [p_W];
    ld.param.s32 r_OH, [p_OH];
    ld.param.s32 r_OW, [p_OW];

    mov.u32 r_tx, %tid.x;
    mov.u32 r_ty, %tid.y;
    mov.u32 r_bx, %ctaid.x;
    mov.u32 r_by, %ctaid.y;
    mov.u32 r_bz, %ctaid.z;
    mov.u32 r_ntx, %ntid.x;
    mov.u32 r_nty, %ntid.y;

    mul.lo.u32 r_x, r_bx, r_ntx;
    add.u32 r_x, r_x, r_tx;
    mul.lo.u32 r_y, r_by, r_nty;
    add.u32 r_y, r_y, r_ty;

    setp.ge.u32 p, r_x, r_OW;
    @p bra DONE;
    setp.ge.u32 p, r_y, r_OH;
    @p bra DONE;

    shr.u32 r_n, r_bz, 5;
    and.b32 r_oc, r_bz, 31;

    mul.wide.u32 r_HW, r_H, r_W;
    shl.b64 r_CHW, r_HW, 1;
    add.u64 r_CHW, r_CHW, r_HW;
    cvt.u64.u32 r_W64, r_W;

    cvt.u64.u32 r_n64, r_n;
    mul.lo.u64 r_base, r_n64, r_CHW;
    mul.wide.u32 r_yW, r_y, r_W;
    add.u64 r_base, r_base, r_yW;
    cvt.u64.u32 r_x64, r_x;
    add.u64 r_base, r_base, r_x64;
    shl.b64 r_base, r_base, 1;
    add.u64 r_inrow, r_in, r_base;

    mul.wide.u32 r_wbase, r_oc, 54;
    add.u64 r_wbase, r_w, r_wbase;

    mov.f32 f_acc, 0f00000000;
    mov.u32 r_ci, 0;
CI_LOOP:
    setp.ge.u32 p, r_ci, 3;
    @p bra STORE;
    cvt.u64.u32 r_ciHW, r_ci;
    mul.lo.u64 r_ciHW, r_ciHW, r_HW;
    mul.lo.u32 r_ci9, r_ci, 9;
    mov.u32 r_ky, 0;
KY_LOOP:
    setp.ge.u32 p, r_ky, 3;
    @p bra KY_END;
    cvt.u64.u32 r_kyW, r_ky;
    mul.lo.u64 r_kyW, r_kyW, r_W64;
    mul.lo.u32 r_wrow, r_ky, 3;
    add.u32 r_wrow, r_wrow, r_ci9;
    mov.u32 r_kx, 0;
KX_LOOP:
    setp.ge.u32 p, r_kx, 3;
    @p bra KX_END;

    cvt.u64.u32 r_delta, r_kx;
    add.u64 r_delta, r_delta, r_ciHW;
    add.u64 r_delta, r_delta, r_kyW;
    shl.b64 r_off, r_delta, 1;
    add.u64 r_addr, r_inrow, r_off;
    ld.global.b16 h_in, [r_addr];
    cvt.f32.bf16 f_in, h_in;

    add.u32 r_tmp32, r_wrow, r_kx;
    cvt.u64.u32 r_off, r_tmp32;
    shl.b64 r_off, r_off, 1;
    add.u64 r_waddr, r_wbase, r_off;
    ld.global.b16 h_w, [r_waddr];
    cvt.f32.bf16 f_w, h_w;

