    mul.wide.u32 r_off, r_OH, r_OW;
    mul.lo.u64 r_n64, r_n64, r_off;
    mul.wide.u32 r_yW, r_y, r_OW;
    add.u64 r_n64, r_n64, r_yW;
    cvt.u64.u32 r_x64, r_x;
    add.u64 r_n64, r_n64, r_x64;
    shl.b64 r_n64, r_n64, 1;
    add.u64 r_addr, r_out, r_n64;
    cvt.rn.bf16.f32 h_out, f_acc;
    st.global.b16 [r_addr], h_out;

