        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x):
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors")
        if x.dtype is not torch.bfloat16:
            raise RuntimeError("ModelNew expects bfloat16 input")
        if x.dim() != 4 or x.shape[1] != 3:
            raise RuntimeError("ModelNew expects NCHW input with 3 channels")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew expects contiguous input")
